from pathlib import Path
import hashlib,json
p=Path(__file__).parent;r=Path('/home/reinsirk/Atcoder_Env');o=p/'opt';sha=lambda b:hashlib.sha256(b).hexdigest()
s=(o/'proposal_set_transform.inc').read_text();old='''// 集合変換は空配列または長さ2^k。各演算はO(n log n)、追加領域O(1)。
// superset_zeta_transform(f): f[S]をSの上位集合の総和へ更新する。
// superset_mobius_transform(f): 上位集合ゼータ変換を元に戻す。
// subset_zeta_transform(f): f[S]をSの部分集合の総和へ更新する。
// subset_mobius_transform(f): 部分集合ゼータ変換を元に戻す。
''';assert s.count(old)==1;s=s.replace(old,'');api='''// 集合4変換: 空配列または長さn=2^kを直接更新、O(1+n log(n+1))時間・O(1)追加領域。
// superset_zeta_transform(f): f[S]を上位集合の総和へ更新、Tの+=が必要。
// superset_mobius_transform(f): 上位集合ゼータ変換の逆、Tの-=が必要。
// subset_zeta_transform(f): f[S]を部分集合の総和へ更新、Tの+=が必要。
// subset_mobius_transform(f): 部分集合ゼータ変換の逆、Tの-=が必要。
// Tはbool以外の加法型。符号付き整数の全途中結果は型の範囲内、符号なしは型の幅の剰余。値演算送出時は部分更新。
''';(r/'Math/Zeta/components/set_transform.inc').write_text(api+s)
s=(o/'proposal_bitwise_convolution.inc').read_text();s=s.replace('// bitwise_and_convolution(f,g): h[k]=sum_{i&j=k}f[i]g[j]。同じ長さ2^k、O(n log n)。\n// bitwise_or_convolution(f,g): h[k]=sum_{i|j=k}f[i]g[j]。同じ長さ2^k、O(n log n)。\n','').replace('// bitwise_and_square(f): h[k]=sum_{i&j=k}f[i]f[j]。長さ2^k、O(n log n)、変換2回。\n','').replace('// bitwise_or_square(f): h[k]=sum_{i|j=k}f[i]f[j]。長さ2^k、O(n log n)、変換2回。\n','');api='''// bitwise_and_convolution(f,g): h[k]=sum_{i&j=k}f[i]g[j]を返す。同長の空配列または長さn=2^k。
// bitwise_or_convolution(f,g): h[k]=sum_{i|j=k}f[i]g[j]を返す。同長の空配列または長さn=2^k。
// bitwise_and_square(f)/bitwise_or_square(f): 同じ式のg=fを返す。入力1本、変換2回（通常の畳み込みは3回）。
// 各APIはO(1+n log(n+1))時間・O(n+1)領域。値渡しのためlvalue入力は保持、rvalueは領域を移譲できる。
// Tはbool以外の環型で+=/-=/*=が必要。符号付き整数の全途中結果は型の範囲内、符号なしは型の幅の剰余。
''';(r/'Math/Zeta/components/bitwise_convolution.inc').write_text(api+s)
print('components installed')

