#include <cstddef>
#include <cstdint>
#include <iostream>
#include <vector>
namespace {
constexpr std::uint32_t mod=998244353;
std::uint32_t add(std::uint32_t a,std::uint32_t b){const auto s=a+b;return s>=mod?s-mod:s;}
std::uint32_t sub(std::uint32_t a,std::uint32_t b){return a>=b?a-b:a+mod-b;}
// 最上位bitで分割しC0=conv(A0+A1,B0+B1)-C1,C1=conv(A1,B1)を再帰的に求める。
void solve(std::uint32_t* a,std::uint32_t* b,std::size_t n){
 if(n==1){*a=static_cast<std::uint32_t>(std::uint64_t(*a)*(*b)%mod);return;}
 const auto h=n/2;
 for(std::size_t i=0;i<h;++i){a[i]=add(a[i],a[h+i]);b[i]=add(b[i],b[h+i]);}
 solve(a,b,h);solve(a+h,b+h,h);
 for(std::size_t i=0;i<h;++i)a[i]=sub(a[i],a[h+i]);
}
}
int main(){std::ios::sync_with_stdio(false);std::cin.tie(nullptr);int k;if(!(std::cin>>k))return 1;const auto n=std::size_t{1}<<k;std::vector<std::uint32_t>a(n),b(n);for(auto&v:a)std::cin>>v;for(auto&v:b)std::cin>>v;solve(a.data(),b.data(),n);for(std::size_t i=0;i<n;++i)std::cout<<a[i]<<(i+1==n?'\n':' ');}

