from pathlib import Path
import subprocess,random,json,hashlib
p=Path(__file__).parent;o=p/'reference_outputs';o.mkdir(exist_ok=True);sha=lambda b:hashlib.sha256(b).hexdigest();cmd=['taskset','-c','6','g++','-std=c++23','-O2','-Wall','-Wextra','-Werror','-pedantic-errors',str(p/'reference.cpp'),'-o',str(p/'reference')];subprocess.run(cmd,capture_output=True,check=True);rng=random.Random(61022);mod=998244353
for t in range(200):
 k=t%8;n=1<<k;a=[rng.randrange(mod)for _ in range(n)];b=[rng.randrange(mod)for _ in range(n)];c=[0]*n
 for i in range(n):
  for j in range(n):c[i&j]=(c[i&j]+a[i]*b[j])%mod
 data=(str(k)+'\n'+' '.join(map(str,a))+'\n'+' '.join(map(str,b))+'\n').encode();out=subprocess.check_output([str(p/'reference')],input=data);assert list(map(int,out.split()))==c
(p/'reference_selfcheck.json').write_text(json.dumps(dict(status='PASS',cases=200,seed=61022,method='最上位bitによるAND畳み込み再帰分解をPythonの多倍長整数O(n²)二重ループと照合',build_command=cmd,source_sha256=sha((p/'reference.cpp').read_bytes())),ensure_ascii=False,indent=2)+'\n');records=[]
for scope in ['official','custom']:
 for row in json.loads((p/(scope+'_cases.json')).read_text()):
  f=p/scope/row['name'];data=f.read_bytes();out=subprocess.check_output([str(p/'reference')],input=data);(o/(f.name+'.out')).write_bytes(out);records.append(dict(scope=scope,name=f.name,input_sha256=sha(data),output_sha256=sha(out),answers=len(out.split())))
(p/'official_reference.json').write_text(json.dumps(dict(status='PASS',source_sha256=sha((p/'reference.cpp').read_bytes()),records=records),indent=2)+'\n');print('independent reference PASS',len(records))

